{-| @Backend.Runtime.Kernel.Csv — the delimiter test and the record scan, as `Pudu.Eval.Csv`
    answers them. -}
module Pudu.Backend.Runtime.Kernel.Csv (csvKernelParts) where

import Data.Text (Text)

{-| Each part: its name, the parts it needs, and its lines. -}
csvKernelParts :: [(Text, [Text], [Text])]
csvKernelParts =
  [ ("csv_delimiter", [],
      [ "/* One byte below 0x80 that is not a quote or a line ending. */"
      , "static int pudu_csv_delimiter(pudu_text delimiter) {"
      , "  return delimiter.length == 1 && delimiter.bytes[0] < 0x80 && delimiter.bytes[0] != '\"' && delimiter.bytes[0] != '\\n' && delimiter.bytes[0] != '\\r';"
      , "}"
      ])
  , ("csv_records", ["array", "array_reserve", "text_allocate", "kernel_int", "memory_failure"],
      [ "/* Well-formed UTF-8, as strict decoding accepts it. */"
      , "static int pudu_csv_text(const unsigned char *b, size_t length) {"
      , "  for (size_t i = 0; i < length;) {"
      , "    unsigned char lead = b[i], low = 0x80, high = 0xBF;"
      , "    size_t width;"
      , "    if (lead < 0x80) { i += 1; continue; }"
      , "    if (lead >= 0xC2 && lead <= 0xDF) width = 2;"
      , "    else if (lead >= 0xE0 && lead <= 0xEF) { width = 3; if (lead == 0xE0) low = 0xA0; if (lead == 0xED) high = 0x9F; }"
      , "    else if (lead >= 0xF0 && lead <= 0xF4) { width = 4; if (lead == 0xF0) low = 0x90; if (lead == 0xF4) high = 0x8F; }"
      , "    else return 0;"
      , "    if (width > length - i || b[i + 1] < low || b[i + 1] > high) return 0;"
      , "    for (size_t k = 2; k < width; ++k) if (b[i + k] < 0x80 || b[i + k] > 0xBF) return 0;"
      , "    i += width;"
      , "  }"
      , "  return 1;"
      , "}"
      , "/* The complete records at the front of the buffer into rows, when rows is"
      , "   there, and the bytes they span. Outside quotes a field ends at the"
      , "   delimiter or a newline; inside, a doubled quote is one quote. A quote in"
      , "   the last byte leaves its record incomplete. Answers 0 when a field is not"
      , "   valid text. The scratch buffer holds one field and is at least the buffer's size. */"
      , "static int pudu_csv_scan(pudu_text buffer, unsigned char delimiter, unsigned char *scratch, pudu_box *rows, size_t *used) {"
      , "  const unsigned char *b = buffer.bytes;"
      , "  size_t size = buffer.length, start = 0;"
      , "  for (;;) {"
      , "    size_t at = start, held = 0;"
      , "    pudu_box *row = rows == NULL ? NULL : pudu_array_new(0);"
      , "    int quoted = 0, complete = 0;"
      , "    while (at < size) {"
      , "      unsigned char byte = b[at];"
      , "      if (quoted) {"
      , "        if (byte != '\"') { scratch[held++] = byte; at += 1; continue; }"
      , "        if (at + 1 >= size) break;"
      , "        if (b[at + 1] == '\"') { scratch[held++] = '\"'; at += 2; continue; }"
      , "        quoted = 0;"
      , "        at += 1;"
      , "        continue;"
      , "      }"
      , "      if (byte == '\"') { quoted = 1; at += 1; continue; }"
      , "      if (byte != delimiter && byte != '\\n') { scratch[held++] = byte; at += 1; continue; }"
      , "      if (byte == '\\n' && held != 0 && scratch[held - 1] == '\\r') held -= 1;"
      , "      /* Only the checking walk can meet a field that is not text. */"
      , "      if (!pudu_csv_text(scratch, held)) return 0;"
      , "      if (row != NULL) {"
      , "        unsigned char *bytes;"
      , "        pudu_array_reserve(row, pudu_array_length(row) + 1);"
      , "        row->fields[0].items->cells[pudu_array_length(row)].text = pudu_text_allocate(held, &bytes);"
      , "        if (held != 0) memcpy(bytes, scratch, held);"
      , "        pudu_array_length(row) += 1;"
      , "      }"
      , "      held = 0;"
      , "      at += 1;"
      , "      if (byte == '\\n') { complete = 1; break; }"
      , "    }"
      , "    if (!complete) {"
      , "      if (row != NULL) {"
      , "        for (size_t i = 0; i < pudu_array_length(row); ++i) pudu_text_release(row->fields[0].items->cells[i].text);"
      , "        free(row->fields[0].items);"
      , "        free(row);"
      , "      }"
      , "      *used = start;"
      , "      return 1;"
      , "    }"
      , "    if (rows != NULL) {"
      , "      pudu_array_reserve(rows, pudu_array_length(rows) + 1);"
      , "      rows->fields[0].items->cells[pudu_array_length(rows)].box = row;"
      , "      pudu_array_length(rows) += 1;"
      , "    }"
      , "    start = at;"
      , "  }"
      , "}"
      , "/* The records, the bytes they span and the characters in those bytes; no"
      , "   box when a field is not valid text. */"
      , "static pudu_box *pudu_csv_records(pudu_box *buffer, pudu_text delimiter) {"
      , "  pudu_text bytes = buffer->fields[0].text;"
      , "  unsigned char *scratch = malloc(bytes.length == 0 ? 1 : bytes.length);"
      , "  size_t used = 0, characters = 0;"
      , "  pudu_box *rows, *answer = NULL;"
      , "  if (scratch == NULL) pudu_memory_failure();"
      , "  if (pudu_csv_scan(bytes, delimiter.bytes[0], scratch, NULL, &used)) {"
      , "    rows = pudu_array_new(0);"
      , "    (void)pudu_csv_scan(bytes, delimiter.bytes[0], scratch, rows, &used);"
      , "    for (size_t i = 0; i < used; ++i) characters += (bytes.bytes[i] & 0xC0) != 0x80;"
      , "    answer = pudu_box_new(3);"
      , "    answer->fields[0].box = rows;"
      , "    answer->fields[1].integer = pudu_kernel_int((int64_t)used);"
      , "    answer->fields[2].integer = pudu_kernel_int((int64_t)characters);"
      , "  }"
      , "  free(scratch);"
      , "  return answer;"
      , "}"
      ])
  ]
